    Compare-side records hold ``Decimal`` values for every JSON number so
    the returned sides keep the report's numeric value and a numeric JSON
    type. Each is emitted as its canonical decimal representation — a
    plain JSON number, never a string, a rounded float or an infinite
    value; trailing zeros and exponent spelling are not preserved.
    """

    def default(self, o):
        if isinstance(o, Decimal):
            raise TypeError("Decimal numbers must be emitted through iterencode")
        return super().default(o)

    def iterencode(self, o, _one_shot=False):
        def floatstr(value):
            if isinstance(value, Decimal):
                return format(value, "f")
            return json.encoder.c_make_encoder and _plain_floatstr(value) or _plain_floatstr(value)

        markers = {} if self.check_circular else None
        if self.ensure_ascii:
            _encoder = json.encoder.encode_basestring_ascii
        else:
            _encoder = json.encoder.encode_basestring
        yield from _json_iterencode(
            o, markers, self.default, _encoder, self.indent,
            _decimal_floatstr, self.key_separator, self.item_separator,
            self.sort_keys, self.skipkeys, _one_shot)


def _plain_floatstr(value):
