# Mirror of json.encoder._make_iterencode with floatstr chosen by value type,
# so Decimal instances are written as raw numbers instead of falling through
# to the float path or being rounded through repr(float(...)).
def _json_iterencode(o, markers, _default, _encoder, _indent, _floatstr,
                     _key_separator, _item_separator, _sort_keys, _skipkeys,
                     _one_shot, _intstr=json.encoder.intstr,
                     ValueError=ValueError, dict=dict, tuple=tuple, list=list,
                     Decimal=Decimal):
    if markers is not None:
        marker_id = id(o)
        if marker_id in markers:
            raise ValueError("Circular reference detected")
        markers[marker_id] = o
    if isinstance(o, str):
        yield _encoder(o)
    elif o is None:
        yield "null"
    elif o is True:
        yield "true"
    elif o is False:
        yield "false"
    elif isinstance(o, int):
        yield _intstr(o)
    elif isinstance(o, float):
        yield _floatstr(o)
    elif isinstance(o, Decimal):
        yield format(o, "f")
    elif isinstance(o, (list, tuple)):
        if not o:
            yield "[]"
        else:
            if markers is not None:
                markers[marker_id] = o
            yield "["
            if _indent is not None:
                _indent += 1
                newline_indent = "\n" + (" " * (_indent * 2))
                separator = _item_separator + newline_indent
                buf = newline_indent
            else:
                newline_indent = None
                separator = _item_separator
                buf = ""
            first = True
            for item in o:
                if isinstance(item, (list, tuple)):
                    pieces = _json_iterencode(
                        item, markers, _default, _encoder, _indent, _floatstr,
                        _key_separator, _item_separator, _sort_keys, _skipkeys,
                        _one_shot)
                    if first:
                        first = False
                    else:
                        yield separator + buf
                    yield from pieces
                else:
                    if first:
                        first = False
                    else:
                        yield separator + buf
                    yield from _json_iterencode(
                        item, markers, _default, _encoder, _indent, _floatstr,
                        _key_separator, _item_separator, _sort_keys, _skipkeys,
                        _one_shot)
            if _indent is not None:
                _indent -= 1
                yield "\n" + (" " * (_indent * 2))
            yield "]"
    elif isinstance(o, dict):
        if not o:
            yield "{}"
        else:
            if markers is not None:
                markers[marker_id] = o
            yield "{"
            if _indent is not None:
                _indent += 1
                newline_indent = "\n" + (" " * (_indent * 2))
                item_separator = _item_separator + newline_indent
                buf = newline_indent
            else:
                newline_indent = None
                item_separator = _item_separator
                buf = ""
            first = True
            if _sort_keys:
                items = sorted(o.items(), key=lambda kv: kv[0])
            else:
                items = o.items()
            for key, value in items:
                if isinstance(key, str):
                    pass
                elif isinstance(key, (int, float, Decimal)) or key is None:
                    key = str(key)
                elif _skipkeys:
                    continue
                else:
                    raise TypeError(
                        f"keys must be str, int, float, Decimal, bool or None, "
                        f"not {key.__class__.__name__}")
                if first:
                    first = False
                else:
                    yield item_separator + buf
                if newline_indent is not None:
                    yield newline_indent
                yield _encoder(key)
                yield _key_separator
                yield from _json_iterencode(
                    value, markers, _default, _encoder, _indent, _floatstr,
                    _key_separator, _item_separator, _sort_keys, _skipkeys,
                    _one_shot)
            if _indent is not None:
                _indent -= 1
                yield "\n" + (" " * (_indent * 2))
            yield "}"
    else:
        yield from _json_iterencode(
            _default(o), markers, _default, _encoder, _indent, _floatstr,
            _key_separator, _item_separator, _sort_keys, _skipkeys, _one_shot)
    if markers is not None:
        del markers[marker_id]


def _compare_dumps(value):
    """Serialize compare output with exact numeric values preserved."""
    return json.dumps(value, ensure_ascii=False, indent=2, cls=_CompareEncoder)

